export function getInitialLanguage(): SupportedLanguage {
  try {
    const saved = localStorage.getItem(USER_LANG_STORAGE_KEY) as SupportedLanguage;
    if (saved && SUPPORTED_LANGUAGES.some(l => l.code === saved)) {
      return saved;
    }
  } catch (e) {}

  try {
    const nav = navigator.language || "";
    const shortCode = nav.split("-")[0].toLowerCase() as SupportedLanguage;
    if (SUPPORTED_LANGUAGES.some(l => l.code === shortCode)) {
      return shortCode;
    }
  } catch (e) {}

  return "ar";
}

export function saveLanguage(lang: SupportedLanguage): void {
  try {
    localStorage.setItem(USER_LANG_STORAGE_KEY, lang);
    const config = SUPPORTED_LANGUAGES.find(l => l.code === lang) || SUPPORTED_LANGUAGES[0];
    document.documentElement.lang = lang;
    document.documentElement.dir = config.dir;
  } catch (e) {}
}

export function t(key: TranslationKey, lang: SupportedLanguage = "ar", fallback?: string): string {
  const dict = TRANSLATIONS[lang] || TRANSLATIONS["ar"];
  if (dict && dict[key]) {
    return dict[key];
  }
  const fallbackDict = TRANSLATIONS["ar"];
  if (fallbackDict && fallbackDict[key]) {
    return fallbackDict[key];
  }
  return fallback || key;
}
